/* ============================================================================
   18. WORK_CATEGORY + WORK_CATEGORY_SKILL — schema, and full data refresh for
   BUSINESS_CATEGORY, SKILL, WORK_CATEGORY, WORK_CATEGORY_SKILL
   ============================================================================
   Source of truth: Category.csv (client-approved master draft — Business
   Category, Work Category / Role, Individual Skills / Responsibilities).

   This is a corrected replacement for an earlier version of this file.
   The previous version's Skill seeding (old Step 4) and Skill-to-Work-
   Category linking (old Step 6) had a bug: it created a placeholder SKILL
   row named the same as its Work Category (e.g. SKILL 'Painter' linked to
   WORK_CATEGORY 'Painter') instead of inserting the real distinct skills
   from the CSV (e.g. Painter should link to 'Surface Preparation' and
   'Painting & Coating' as two separate skills). That is fixed below —
   Steps 1/2/3/5 (table creation, Business Category, Work Category) are
   unchanged from the original, since they were already correct.

   This script is SELF-CONTAINED: it creates WORK_CATEGORY and
   WORK_CATEGORY_SKILL from scratch (Step 1) if they don't already exist.

   SAFE TO RE-RUN, including on a database where the OLD buggy version of
   this file already ran — Step 5b below detects and cleans up the bad
   self-named rows before the correct data is inserted.
   ============================================================================ */

-- ────────────────────────────────────────────────────────────────────────
-- STEP 1: Create WORK_CATEGORY and WORK_CATEGORY_SKILL tables (new — this
-- is the 3rd table set requested, alongside your existing BUSINESS_CATEGORY
-- and SKILL tables).
-- ────────────────────────────────────────────────────────────────────────

IF NOT EXISTS (SELECT 1 FROM sys.tables WHERE name = 'WORK_CATEGORY')
BEGIN
    CREATE TABLE dbo.WORK_CATEGORY (
        WORK_CATEGORY_ID     INT IDENTITY(1,1) PRIMARY KEY,
        BUSINESS_CATEGORY_ID INT NOT NULL,
        CATEGORY_NAME        NVARCHAR(200) NOT NULL,
        IS_ACTIVE_FL         BIT NOT NULL DEFAULT 1,
        CREATED_BY           NVARCHAR(100) NOT NULL DEFAULT 'SYSTEM_SEED',
        CREATED_TS           DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),
        CREATED_IP_ADDR      NVARCHAR(50) NULL,
        UPDATED_BY           NVARCHAR(100) NULL,
        UPDATED_TS           DATETIME2 NULL,
        UPDATED_IP_ADDR      NVARCHAR(50) NULL,
        CONSTRAINT FK_WORK_CATEGORY_BUSINESS_CATEGORY
            FOREIGN KEY (BUSINESS_CATEGORY_ID) REFERENCES dbo.BUSINESS_CATEGORY(BUSINESS_CATEGORY_ID)
    );
END;
GO

IF NOT EXISTS (SELECT 1 FROM sys.tables WHERE name = 'WORK_CATEGORY_SKILL')
BEGIN
    CREATE TABLE dbo.WORK_CATEGORY_SKILL (
        WORK_CATEGORY_SKILL_ID INT IDENTITY(1,1) PRIMARY KEY,
        WORK_CATEGORY_ID       INT NOT NULL,
        SKILL_ID                INT NOT NULL,
        RESPONSIBILITY_TXT      NVARCHAR(500) NULL,
        IS_ACTIVE_FL             BIT NOT NULL DEFAULT 1,
        CREATED_BY               NVARCHAR(100) NOT NULL DEFAULT 'SYSTEM_SEED',
        CREATED_TS               DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),
        CREATED_IP_ADDR          NVARCHAR(50) NULL,
        UPDATED_BY               NVARCHAR(100) NULL,
        UPDATED_TS               DATETIME2 NULL,
        UPDATED_IP_ADDR          NVARCHAR(50) NULL,
        CONSTRAINT FK_WORK_CATEGORY_SKILL_WORK_CATEGORY
            FOREIGN KEY (WORK_CATEGORY_ID) REFERENCES dbo.WORK_CATEGORY(WORK_CATEGORY_ID),
        CONSTRAINT FK_WORK_CATEGORY_SKILL_SKILL
            FOREIGN KEY (SKILL_ID) REFERENCES dbo.SKILL(SKILL_ID)
    );
END;
GO

-- If WORK_CATEGORY_SKILL already existed from an earlier draft of this
-- script without RESPONSIBILITY_TXT, add it now.
IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('WORK_CATEGORY_SKILL') AND name = 'RESPONSIBILITY_TXT')
    ALTER TABLE dbo.WORK_CATEGORY_SKILL ADD RESPONSIBILITY_TXT NVARCHAR(500) NULL;
GO


-- ────────────────────────────────────────────────────────────────────────
