-- ────────────────────────────────────────────────────────────────────────
-- STEP 5b: Clean up bad rows left by a previous run of the OLD buggy
-- version of this file (self-named Skill-to-Work-Category links)
-- ────────────────────────────────────────────────────────────────────────

DELETE wcs
FROM dbo.WORK_CATEGORY_SKILL wcs
JOIN dbo.WORK_CATEGORY wc ON wc.WORK_CATEGORY_ID = wcs.WORK_CATEGORY_ID
JOIN dbo.SKILL s ON s.SKILL_ID = wcs.SKILL_ID
WHERE LOWER(LTRIM(RTRIM(s.SKILL_NAME))) = LOWER(LTRIM(RTRIM(wc.CATEGORY_NAME)));
GO

UPDATE s
SET s.IS_ACTIVE_FL = 0, s.UPDATED_BY = 'MIGRATION_18_CLEANUP', s.UPDATED_TS = SYSUTCDATETIME()
FROM dbo.SKILL s
JOIN dbo.WORK_CATEGORY wc ON LOWER(LTRIM(RTRIM(wc.CATEGORY_NAME))) = LOWER(LTRIM(RTRIM(s.SKILL_NAME)))
WHERE NOT EXISTS (SELECT 1 FROM dbo.WORK_CATEGORY_SKILL wcs WHERE wcs.SKILL_ID = s.SKILL_ID)
  AND NOT EXISTS (SELECT 1 FROM dbo.EMPLOYEE_SKILL es WHERE es.SKILL_ID = s.SKILL_ID)
  AND NOT EXISTS (SELECT 1 FROM dbo.JOB_SKILL js WHERE js.SKILL_ID = s.SKILL_ID)
  AND NOT EXISTS (SELECT 1 FROM dbo.LEARNING_VIDEO lv WHERE lv.SKILL_ID = s.SKILL_ID);
GO


-- ────────────────────────────────────────────────────────────────────────
-- STEP 6: Map every Work Category to its correct Skills (from Category.csv)
-- ────────────────────────────────────────────────────────────────────────

/* ---- 4. Link every Work Category to its real skills (idempotent) --------- */
IF NOT EXISTS (
    SELECT 1 FROM dbo.WORK_CATEGORY_SKILL wcs
    JOIN dbo.WORK_CATEGORY wc ON wc.WORK_CATEGORY_ID = wcs.WORK_CATEGORY_ID
    JOIN dbo.BUSINESS_CATEGORY bc ON bc.BUSINESS_CATEGORY_ID = wc.BUSINESS_CATEGORY_ID
    JOIN dbo.SKILL s ON s.SKILL_ID = wcs.SKILL_ID
    WHERE LOWER(LTRIM(RTRIM(wc.CATEGORY_NAME))) = LOWER(N'Steward / Waiter')
      AND LOWER(LTRIM(RTRIM(bc.CATEGORY_NAME))) = LOWER(N'Restaurants / QSR / Cafés / Cloud Kitchens')
      AND LOWER(LTRIM(RTRIM(s.SKILL_NAME))) = LOWER(N'Table Service')
)
    INSERT INTO dbo.WORK_CATEGORY_SKILL (WORK_CATEGORY_ID, SKILL_ID, RESPONSIBILITY_TXT, IS_ACTIVE_FL, CREATED_BY)
    SELECT wc.WORK_CATEGORY_ID, s.SKILL_ID, N'Table Service', 1, 'SYSTEM_SEED_MASTER_DRAFT_CSV'
    FROM dbo.WORK_CATEGORY wc
    JOIN dbo.BUSINESS_CATEGORY bc ON bc.BUSINESS_CATEGORY_ID = wc.BUSINESS_CATEGORY_ID
    CROSS JOIN dbo.SKILL s
