    JOIN dbo.WORK_CATEGORY wc ON wc.WORK_CATEGORY_ID = wcs.WORK_CATEGORY_ID
    JOIN dbo.BUSINESS_CATEGORY bc ON bc.BUSINESS_CATEGORY_ID = wc.BUSINESS_CATEGORY_ID
    JOIN dbo.SKILL s ON s.SKILL_ID = wcs.SKILL_ID
    WHERE LOWER(LTRIM(RTRIM(wc.CATEGORY_NAME))) = LOWER(N'Delivery Executive / Rider')
      AND LOWER(LTRIM(RTRIM(bc.CATEGORY_NAME))) = LOWER(N'Logistics / Courier / E-commerce')
      AND LOWER(LTRIM(RTRIM(s.SKILL_NAME))) = LOWER(N'Customer Handover')
)
