    SELECT wc.WORK_CATEGORY_ID, s.SKILL_ID, N'Customer Handover', 1, 'SYSTEM_SEED_MASTER_DRAFT_CSV'
    FROM dbo.WORK_CATEGORY wc
    JOIN dbo.BUSINESS_CATEGORY bc ON bc.BUSINESS_CATEGORY_ID = wc.BUSINESS_CATEGORY_ID
    CROSS JOIN dbo.SKILL s
    WHERE LOWER(LTRIM(RTRIM(wc.CATEGORY_NAME))) = LOWER(N'Delivery Executive / Rider')
