/* ---- 5. Verification — run after, should show 216 rows / 0 self-named ---- */
SELECT COUNT(*) AS TOTAL_WORK_CATEGORY_SKILL_LINKS FROM dbo.WORK_CATEGORY_SKILL;

SELECT COUNT(*) AS REMAINING_SELF_NAMED_BUG_ROWS
FROM dbo.WORK_CATEGORY_SKILL wcs
JOIN dbo.WORK_CATEGORY wc ON wc.WORK_CATEGORY_ID = wcs.WORK_CATEGORY_ID
JOIN dbo.SKILL s ON s.SKILL_ID = wcs.SKILL_ID
WHERE LOWER(LTRIM(RTRIM(s.SKILL_NAME))) = LOWER(LTRIM(RTRIM(wc.CATEGORY_NAME)));

SELECT bc.CATEGORY_NAME AS BUSINESS_CATEGORY, wc.CATEGORY_NAME AS WORK_CATEGORY, s.SKILL_NAME
FROM dbo.WORK_CATEGORY_SKILL wcs
JOIN dbo.WORK_CATEGORY wc ON wc.WORK_CATEGORY_ID = wcs.WORK_CATEGORY_ID
JOIN dbo.BUSINESS_CATEGORY bc ON bc.BUSINESS_CATEGORY_ID = wc.BUSINESS_CATEGORY_ID
JOIN dbo.SKILL s ON s.SKILL_ID = wcs.SKILL_ID
WHERE wc.CATEGORY_NAME = N'Painter'
ORDER BY bc.CATEGORY_NAME, wc.CATEGORY_NAME, s.SKILL_NAME;